import{c as r,$ as e,Q as s,j as y,g as t,n as p,o,m as i}from"./chunks/framework.CWBTDBPu.js";const f=JSON.parse('{"title":"YuPay 命令手册","description":"","frontmatter":{"title":"YuPay 命令手册"},"headers":[],"relativePath":"plugins/items/yupay/commands.md","filePath":"plugins/items/yupay/commands.md"}'),n={name:"plugins/items/yupay/commands.md"},l={class:"quick-actions"};function h(u,d,k,m,g,F){const c=e("CopyMarkdownButton"),a=e("CopyLLMButton");return s(),y("div",null,[d[0]||(d[0]=t("h1",{id:"yupay-命令手册",tabindex:"-1"},[p("YuPay 命令手册 "),t("a",{class:"header-anchor",href:"#yupay-命令手册","aria-label":'Permalink to "YuPay 命令手册"'},"​")],-1)),t("div",l,[o(c,{page:""}),o(a,{page:""})]),d[1]||(d[1]=i(`<p>YuPay 有三个独立玩家入口和一个综合入口。日常建议把 <code>/yp</code> 作为主入口写进公告或菜单，独立命令可按服务器习惯保留或改名。</p><h2 id="主命令与别名" tabindex="-1">主命令与别名 <a class="header-anchor" href="#主命令与别名" aria-label="Permalink to &quot;主命令与别名&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>别名</th><th>用途</th></tr></thead><tbody><tr><td><code>/yupaypay &lt;金额&gt;</code></td><td><code>/ypay</code></td><td>独立赞助命令</td></tr><tr><td><code>/yupaytop</code></td><td><code>/yptop</code></td><td>独立排行榜命令</td></tr><tr><td><code>/yupaytotal [玩家名]</code></td><td><code>/yptotal</code></td><td>独立总额查询命令</td></tr><tr><td><code>/yupay &lt;子命令&gt;</code></td><td><code>/yp</code></td><td>综合管理与玩家自助入口</td></tr></tbody></table><p>综合入口 <code>/yp</code> 内部注册了 <code>pay</code>、<code>top</code>、<code>total</code>、<code>history</code>、<code>orders</code>、<code>order</code>、<code>cancel</code>、<code>retry</code>、<code>code</code>、<code>refund</code>、<code>audit</code>、<code>health</code> 等子命令。</p><h2 id="玩家命令" tabindex="-1">玩家命令 <a class="header-anchor" href="#玩家命令" aria-label="Permalink to &quot;玩家命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>/yp pay &lt;金额&gt; [支付方式] [输出模式] [-n]</code></td><td><code>yupay.command.pay</code></td><td>发起赞助。支付方式通常为 <code>wechat</code> 或 <code>alipay</code>；输出模式可用 <code>text</code>、<code>link</code>、<code>map</code>；<code>-n</code> 表示无偿赞助，不触发奖励。</td><td><code>/yp pay 30 wechat map</code></td></tr><tr><td><code>/yp top</code></td><td><code>yupay.command.top</code></td><td>查看赞助排行榜前 10。</td><td><code>/yp top</code></td></tr><tr><td><code>/yp total [玩家/all]</code></td><td><code>yupay.command.total</code></td><td>查询自己、指定玩家或全服累计赞助额。</td><td><code>/yp total</code></td></tr><tr><td><code>/yp history [页数]</code></td><td><code>yupay.command.history</code></td><td>查看自己的赞助历史；管理员可追加玩家名查看他人历史。</td><td><code>/yp history 2</code></td></tr><tr><td><code>/yp orders [页数]</code></td><td><code>yupay.command.orders</code></td><td>查看自己的订单列表。</td><td><code>/yp orders</code></td></tr><tr><td><code>/yp order &lt;订单号&gt;</code></td><td><code>yupay.command.orders</code></td><td>查看自己的订单详情；待支付订单会提示取消，奖励异常订单会提示重试。</td><td><code>/yp order YP202606010001</code></td></tr><tr><td><code>/yp cancel [订单号]</code></td><td><code>yupay.command.cancel</code></td><td>取消自己的待支付订单；不填订单号时通常处理最近待支付订单。</td><td><code>/yp cancel</code></td></tr><tr><td><code>/yp retry [订单号]</code></td><td><code>yupay.command.retry</code></td><td>自助重试补发奖励，适合支付成功但奖励卡住的订单。</td><td><code>/yp retry YP202606010001</code></td></tr><tr><td><code>/yp code redeem &lt;卡密&gt;</code></td><td><code>yupay.command.code</code> + <code>yupay.code.redeem</code></td><td>核销卡密。插件会先展示确认信息，再进入确认/取消流程。</td><td><code>/yp code redeem FREEGIFT</code></td></tr><tr><td><code>/yp refund request &lt;订单号&gt; [金额]</code></td><td><code>yupay.command.refund</code> + <code>yupay.refund.request</code></td><td>创建退款申请；不填金额时按插件逻辑处理可退金额。</td><td><code>/yp refund request YP202606010001 6.66</code></td></tr></tbody></table><h2 id="管理命令" tabindex="-1">管理命令 <a class="header-anchor" href="#管理命令" aria-label="Permalink to &quot;管理命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/yp reload</code></td><td><code>yupay.reload</code></td><td>重载配置、语言和运行时缓存。</td></tr><tr><td><code>/yp set &lt;选项&gt; &lt;值&gt;</code></td><td><code>yupay.admin</code></td><td>修改插件配置项。</td></tr><tr><td><code>/yp config</code></td><td><code>yupay.admin</code></td><td>查看当前配置或配置辅助信息。</td></tr><tr><td><code>/yp ban &lt;玩家/all&gt; [原因]</code></td><td><code>yupay.ban</code></td><td>禁止玩家发起赞助。</td></tr><tr><td><code>/yp unban &lt;玩家/all&gt;</code></td><td><code>yupay.ban</code></td><td>解除赞助禁止。</td></tr><tr><td><code>/yp convert &lt;玩家&gt; &lt;来源类型&gt; &lt;目标类型&gt; &lt;数量&gt;</code></td><td><code>yupay.convert</code></td><td>货币转换，常用于 Vault 与 PlayerPoints 场景。</td></tr><tr><td><code>/yp audit</code></td><td><code>yupay.audit</code></td><td>查看事件监听审计信息。</td></tr><tr><td><code>/yp audit security [lines]</code></td><td><code>yupay.audit</code></td><td>查看安全审计日志最近记录。</td></tr><tr><td><code>/yp health [summary/full]</code></td><td><code>yupay.health</code></td><td>运行健康检查，排查支付渠道、数据库、依赖和回调状态。</td></tr><tr><td><code>/yp crossserver [status/queue]</code></td><td><code>yupay.crossserver</code></td><td>查看跨服发奖状态和队列统计。</td></tr></tbody></table><h2 id="卡密命令" tabindex="-1">卡密命令 <a class="header-anchor" href="#卡密命令" aria-label="Permalink to &quot;卡密命令&quot;">​</a></h2><p>卡密入口统一为 <code>/yp code ...</code>，普通玩家只需要 <code>redeem</code>；后台运营再按需分配创建、修改、删除、列表和日志权限。</p><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/yp code create --code &lt;卡密&gt; [选项]</code></td><td><code>yupay.code.create</code></td><td>创建卡密。</td></tr><tr><td><code>/yp code remove &lt;卡密&gt;</code></td><td><code>yupay.code.remove</code></td><td>数据库层面删除卡密，核销日志保留。</td></tr><tr><td><code>/yp code disable &lt;卡密&gt;</code></td><td><code>yupay.code.disable</code></td><td>软停用卡密。</td></tr><tr><td><code>/yp code enable &lt;卡密&gt;</code></td><td><code>yupay.code.enable</code></td><td>恢复启用卡密。</td></tr><tr><td><code>/yp code modify &lt;卡密&gt; &lt;字段&gt; &lt;值&gt;</code></td><td><code>yupay.code.modify</code></td><td>修改卡密字段。</td></tr><tr><td><code>/yp code info &lt;卡密&gt;</code></td><td><code>yupay.code.info</code></td><td>查看卡密详情。</td></tr><tr><td><code>/yp code list [页数]</code></td><td><code>yupay.code.list</code></td><td>查看卡密列表。</td></tr><tr><td><code>/yp code logs [卡密] [页数]</code></td><td><code>yupay.code.logs</code></td><td>查看核销记录。</td></tr><tr><td><code>/yp code redeem &lt;卡密&gt;</code></td><td><code>yupay.code.redeem</code></td><td>玩家核销卡密。</td></tr><tr><td><code>/yp code redeem-confirm &lt;卡密&gt;</code></td><td><code>yupay.code.redeem</code></td><td>确认核销。</td></tr><tr><td><code>/yp code redeem-cancel [卡密]</code></td><td><code>yupay.code.redeem</code></td><td>取消核销。</td></tr></tbody></table><p>创建卡密的常用选项：</p><table tabindex="0"><thead><tr><th>选项</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>--code</code></td><td><code>--code FREEGIFT</code></td><td>卡密字符串。</td></tr><tr><td><code>--amount</code></td><td><code>--amount 9.9</code></td><td>卡密关联的支付金额。</td></tr><tr><td><code>--economy</code></td><td><code>--economy playerpoints</code></td><td>经济奖励类型：<code>none</code>、<code>vault</code>、<code>playerpoints</code>、<code>pp</code>。</td></tr><tr><td><code>--eco-amount</code></td><td><code>--eco-amount 100</code></td><td>经济奖励数量。</td></tr><tr><td><code>--max-uses</code></td><td><code>--max-uses 50</code></td><td>最大核销次数；<code>-1</code> 表示不限次数。</td></tr><tr><td><code>--expire</code></td><td><code>--expire 7d</code></td><td>过期时间；<code>-1</code> 表示永不过期。</td></tr><tr><td><code>--commands</code></td><td><code>--commands &quot;give {player} diamond 1&quot;</code></td><td>核销后执行的命令。</td></tr><tr><td><code>--remark</code></td><td><code>--remark &quot;全服礼包&quot;</code></td><td>备注。</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/yp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FREEGIFT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --amount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --economy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playerpoints</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --eco-amount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-uses</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --expire</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 7d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --remark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;新服礼包&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/yp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FREEGIFT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> max-uses</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/yp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FREEGIFT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div><h2 id="退款命令" tabindex="-1">退款命令 <a class="header-anchor" href="#退款命令" aria-label="Permalink to &quot;退款命令&quot;">​</a></h2><p>退款入口统一为 <code>/yp refund ...</code>。普通玩家只开放 <code>request</code> 即可；直接退款、审核、查询和重试建议只给财务或核心管理员。</p><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/yp refund request &lt;订单号&gt; [金额]</code></td><td><code>yupay.refund.request</code></td><td>玩家创建退款申请。</td></tr><tr><td><code>/yp refund approve &lt;请求ID&gt;</code></td><td><code>yupay.refund.approve</code></td><td>通过退款申请。</td></tr><tr><td><code>/yp refund reject &lt;请求ID&gt;</code></td><td><code>yupay.refund.reject</code></td><td>拒绝退款申请。</td></tr><tr><td><code>/yp refund pending [页数]</code></td><td><code>yupay.refund.pending</code></td><td>查看待审核申请。</td></tr><tr><td><code>/yp refund list [页数]</code></td><td><code>yupay.refund.list</code></td><td>查看退款日志列表。</td></tr><tr><td><code>/yp refund list &lt;pending/processing/accepted/success/failed/closed/unknown&gt; [页]</code></td><td><code>yupay.refund.list</code></td><td>按状态查看退款流水。</td></tr><tr><td><code>/yp refund info &lt;退款单号&gt;</code></td><td><code>yupay.refund.list</code></td><td>查看退款流水详情。</td></tr><tr><td><code>/yp refund query &lt;退款单号&gt;</code></td><td><code>yupay.refund.list</code></td><td>向平台查询退款状态并刷新本地记录。</td></tr><tr><td><code>/yp refund retry &lt;退款单号&gt;</code></td><td><code>yupay.refund.direct</code></td><td>重试失败或未知状态退款。</td></tr><tr><td><code>/yp refund confirm &lt;退款单号&gt;</code></td><td><code>yupay.refund.direct</code></td><td>手动确认退款成功。</td></tr><tr><td><code>/yp refund &lt;订单号&gt; [金额] [原因]</code></td><td><code>yupay.refund.direct</code></td><td>管理员直接退款。</td></tr></tbody></table><h2 id="订单运维命令" tabindex="-1">订单运维命令 <a class="header-anchor" href="#订单运维命令" aria-label="Permalink to &quot;订单运维命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/yp order info &lt;订单号&gt;</code></td><td><code>yupay.order</code> 或玩家自己的 <code>yupay.command.orders</code></td><td>查看订单详情。</td></tr><tr><td><code>/yp order abnormal [页]</code></td><td><code>yupay.order</code></td><td>查看异常订单中心。</td></tr><tr><td><code>/yp order risk [页]</code></td><td><code>yupay.order</code></td><td>查看风险订单。</td></tr><tr><td><code>/yp order list &lt;abnormal/pending/cancelled/risk/reward_failed/refund_failed/success&gt; [页]</code></td><td><code>yupay.order</code></td><td>按类型列出订单。</td></tr><tr><td><code>/yp order player &lt;玩家名/UUID&gt; [页]</code></td><td><code>yupay.order</code></td><td>查看某玩家订单。</td></tr><tr><td><code>/yp order steps &lt;订单号&gt;</code></td><td><code>yupay.order</code></td><td>查看发奖步骤流水。</td></tr><tr><td><code>/yp order callbacks &lt;订单号/recent/failed/duplicate&gt; [页]</code></td><td><code>yupay.order</code></td><td>查看回调流水。</td></tr><tr><td><code>/yp order refunds &lt;订单号&gt; [页]</code></td><td><code>yupay.order</code></td><td>查看订单退款流水。</td></tr><tr><td><code>/yp order resolve &lt;订单号&gt; &lt;reward/refund/ignore/hold&gt;</code></td><td><code>yupay.order</code></td><td>处理取消后到账、金额不符等风险订单。</td></tr><tr><td><code>/yp order mark-reviewed &lt;订单号&gt; [备注]</code></td><td><code>yupay.order</code></td><td>标记订单已人工复核。</td></tr><tr><td><code>/yp order retry-reward &lt;订单号&gt;</code></td><td><code>yupay.order</code></td><td>管理员重试发奖。</td></tr><tr><td><code>/yp order expire</code></td><td><code>yupay.order</code></td><td>立即执行待支付订单过期清理。</td></tr></tbody></table>`,19))])}const C=r(n,[["render",h]]);export{f as __pageData,C as default};
